1	package retention
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"sync"
13		"syscall"
14	)
15	
16	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
17	const (
18		stateFileName = "retention-state.json"
19		lockFileName  = ".retention.lock"
20	)
21	
22	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
23	//
24	// 同一个目录可以被本机上的多个程序（进程）同时打开：
25	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
26	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
27	type Store struct {
28		dir string
29	
30		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
31		opMu sync.RWMutex
32	}
33	
34	// Open 打开（或创建）一个本地保存位置。
35	// 目录不存在时会创建；状态文件不存在时按空库打开，可以正常登记。
36	// 状态文件已存在但内容损坏（空文件、只有空白、内容为 null、合法对象后面
37	// 还拼接了其他内容等），或其中保存的记录不满足业务不变量（例如已解除冻结
38	// 缺少解除原因或解除日期、解除日期早于冻结日期、已销毁档案与已关闭清册
39	// 对应不上）时返回 ErrCorruptState，
40	// 不会返回可继续办理的保管库，已有记录保持原样，不会被清空、修补或覆盖。
41	func Open(dir string) (*Store, error) {
42		if dir == "" {
43			return nil, errors.New("retention: 保存位置不能为空")
44		}
45		if err := os.MkdirAll(dir, 0o755); err != nil {
46			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
47		}
48		s := &Store{dir: dir}
49		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
50		if _, err := s.load(); err != nil {
51			return nil, err
52		}
53		return s, nil
54	}
55	
56	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
57	func (s *Store) Close() error { return nil }
58	
59	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
60	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
61	
62	// lock 取得跨进程排他锁，返回解锁函数。
63	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
64	func (s *Store) lock() (func(), error) {
65		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
66		if err != nil {
67			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
68		}
69		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
70			f.Close()
71			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
72		}
73		return func() {
74			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
75			_ = f.Close()
76		}, nil
77	}
78	
79	// rlock 取得跨进程共享锁，用于只读核对。
80	func (s *Store) rlock() (func(), error) {
81		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
82		if err != nil {
83			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
84		}
85		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
86			f.Close()
87			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
88		}
89		return func() {
90			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
91			_ = f.Close()
92		}, nil
93	}
94	
95	// load 从磁盘读取最新状态。文件不存在时返回一份空状态（尚未建立记录）。
96	//
97	// 文件已经存在时，必须完整包含且只包含一个 JSON 对象（前后允许空白）：
98	// 零字节或只有空白的文件、内容为 null 的文件、合法对象后面还拼接了
99	// 第二个 JSON 值或无法解析的文字，都判为损坏并返回 ErrCorruptState，
100	// 绝不只使用前一段内容，也不会改动原文件。
101	//
102	// JSON 能解析不代表记录合法：任何已解除冻结都必须同时带有非空白的
103	// 解除原因和有效的解除日期，且解除日期不早于冻结日期——与解除功能
104	// 办理时的要求一致。缺少任一信息或日期顺序不成立时，整份保管库同样
105	// 判为损坏并返回 ErrCorruptState，错误信息指明涉及的档案与冻结编号。
106	//
107	// 已销毁档案与已关闭清册也必须相互对应：每份已销毁档案记下的申请编号
108	// 必须能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案
109	// 也必须存在、标成已销毁并指回这份清册。已销毁档案找不到清册、同一档案
110	// 出现在多份清册、归属指向别的申请，或未销毁档案仍挂有清册申请编号，
111	// 都说明记录已无法说明档案由哪次申请销毁，整份保管库判为损坏并返回
112	// ErrCorruptState，错误信息指明涉及的档案编号与相关申请编号。
113	//
114	// 最初截止日、修订记录与当前截止日也必须连续对应：第一条修订的原截止日
115	// 等于最初截止日，后续每条的原截止日等于上一条的新截止日，最后一条的
116	// 新截止日等于当前截止日；没有修订时最初截止日与当前截止日相同。修订
117	// 日期仅用于记录，历史不按该日期重新排列。出现断开的修订关系、当前截止日
118	// 与末次修订不符、修订列表中存在空记录，或已有修订却缺少最初截止日时，
119	// 两个日期中任何一个都不能当作可靠依据，整份保管库判为损坏并返回
120	// ErrCorruptState，错误信息指明涉及的档案编号，能对应到具体修订时
121	// 同时指明修订编号。
122	func (s *Store) load() (*storeData, error) {
123		raw, err := os.ReadFile(s.statePath())
124		if err != nil {
125			if errors.Is(err, os.ErrNotExist) {
126				return newStoreData(), nil
127			}
128			return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
129		}
130		trimmed := bytes.TrimSpace(raw)
131		if len(trimmed) == 0 {
132			return nil, fmt.Errorf("retention: 状态文件为空或只有空白: %w", ErrCorruptState)
133		}
134		// json.Unmarshal 对 null 不报错且保持目标不变，必须单独拒绝。
135		if string(trimmed) == "null" {
136			return nil, fmt.Errorf("retention: 状态文件内容为 null，不是有效的保管库记录: %w", ErrCorruptState)
137		}
138		data := newStoreData()
139		// json.Unmarshal 要求整个输入恰好是一个 JSON 值：
140		// 合法对象后面再拼接任何内容都会在这里报错。
141		if err := json.Unmarshal(raw, data); err != nil {
142			return nil, fmt.Errorf("retention: 状态文件内容无法解析: %v: %w", err, ErrCorruptState)
143		}
144		if data.Archives == nil {
145			data.Archives = map[string]*archiveRecord{}
146		}
147		if data.Manifests == nil {
148			data.Manifests = map[string]*manifestRecord{}
149		}
150		// 语义校验先于任何兼容处理：已解除冻结必须与既有解除功能遵守同一要求——
151		// 解除原因与解除日期齐备，且解除日期不早于冻结日期。
152		// 只有“已解除”标记而缺少任一信息，或解除日期早于冻结日期的记录
153		// 一律判为损坏（即使所属档案已销毁）；绝不据此继续办理或修补记录。
154		if err := validateFreezeReleaseRecords(data); err != nil {
155			return nil, err
156		}
157		// 已销毁档案与已关闭清册必须相互对应，否则无法说明档案由哪次申请销毁。
158		// 关系损坏时绝不挑选其中一份记录继续使用，也不补清册或改销毁标记。
159		if err := validateManifestConsistency(data); err != nil {
160			return nil, err
161		}
162		// 兼容引入修订功能之前保存的保管库：没有修订记录也没有最初截止日时，
163		// 登记截止日就是最初截止日。已有修订却缺少最初截止日的记录不能据此
164		// 冒充，由 validateRevisionContinuity 按损坏拒绝。
165		for _, ar := range data.Archives {
166			if ar != nil && len(ar.Revisions) == 0 && ar.InitialEnd.IsZero() {
167				ar.InitialEnd = ar.End
168			}
169		}
170		// 最初截止日、修订记录与当前截止日必须连续衔接，否则当前期限与
171		// 历史期限相互矛盾，任何一个日期都不能当作核对依据。
172		if err := validateRevisionContinuity(data); err != nil {
173			return nil, err
174		}
175		return data, nil
176	}
177	
178	// validateFreezeReleaseRecords 检查库内全部已解除冻结记录是否完整合法。
179	//
180	// 正常解除保存的记录必然同时带有非空白的解除原因和有效的解除日期，
181	// 且解除日期不早于冻结日期。缺少解除原因、解除日期缺失或为 null、
182	// 解除日期早于冻结日期，都说明保存内容已损坏，返回可由 ErrCorruptState
183	// 识别的错误，并在信息中给出涉及的档案编号与冻结编号，便于定位记录。
184	// 校验覆盖整个保管库的全部已解除冻结，与本次办理名单无关：
185	// 即使异常记录所属档案已经销毁，也不能把不完整的解除信息当作正常历史。
186	// 未解除冻结没有解除日期和原因是合法状态，不在此报错。
187	func validateFreezeReleaseRecords(data *storeData) error {
188		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
189		archiveIDs := make([]string, 0, len(data.Archives))
190		for id := range data.Archives {
191			archiveIDs = append(archiveIDs, id)
192		}
193		sort.Strings(archiveIDs)
194		for _, id := range archiveIDs {
195			ar := data.Archives[id]
196			if ar == nil {
197				return fmt.Errorf("retention: 档案 %s 的登记记录缺失，状态文件已损坏: %w",
198					id, ErrCorruptState)
199			}
200			for _, fr := range ar.Freezes {
201				if fr == nil {
202					return fmt.Errorf("retention: 档案 %s 下存在缺失的冻结记录，状态文件已损坏: %w",
203						id, ErrCorruptState)
204				}
205				if !fr.Released {
206					// 未解除冻结没有解除日期与原因是合法状态。
207					continue
208				}
209				switch {
210				case strings.TrimSpace(fr.ReleaseReason) == "":
211					return fmt.Errorf(
212						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除原因，记录已损坏: %w",
213						id, fr.ID, ErrCorruptState)
214				case fr.ReleasedOn == nil:
215					return fmt.Errorf(
216						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除日期，记录已损坏: %w",
217						id, fr.ID, ErrCorruptState)
218				case fr.ReleasedOn.IsZero():
219					return fmt.Errorf(
220						"retention: 档案 %s 的冻结 %s 的解除日期无效，记录已损坏: %w",
221						id, fr.ID, ErrCorruptState)
222				case fr.ReleasedOn.Before(fr.FrozenOn):
223					return fmt.Errorf(
224						"retention: 档案 %s 的冻结 %s 的解除日期 %s 早于冻结日期 %s，记录已损坏: %w",
225						id, fr.ID, fr.ReleasedOn, fr.FrozenOn, ErrCorruptState)
226				}
227			}
228		}
229		return nil
230	}
231	
232	// validateManifestConsistency 检查已销毁档案与已关闭清册之间的对应关系。
233	//
234	// 正常销毁保存的记录必然满足双向对应：每份已销毁档案记下的申请编号
235	// 能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案都
236	// 存在、标成已销毁，并指回这份清册。已销毁档案没有清册归属、归属的
237	// 清册不存在或未收录该档案、同一档案出现在多份清册、清册重复收录同一
238	// 档案、清册收录了不存在或未销毁的档案、档案归属指向别的申请，以及
239	// 未销毁档案仍挂有清册申请编号，都说明保存内容已损坏，返回可由
240	// ErrCorruptState 识别的错误，并在信息中给出涉及的档案编号与相关
241	// 申请编号，便于定位记录。校验覆盖整个保管库，与本次办理名单无关；
242	// 未销毁且没有清册归属的档案是合法记录，不在此报错。
243	func validateManifestConsistency(data *storeData) error {
244		// map 遍历顺序不稳定，按编号排序后再检查，保证错误信息稳定。
245		archiveIDs := make([]string, 0, len(data.Archives))
246		for id := range data.Archives {
247			archiveIDs = append(archiveIDs, id)
248		}
249		sort.Strings(archiveIDs)
250		for _, id := range archiveIDs {
251			ar := data.Archives[id]
252			if ar == nil {
253				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
254				continue
255			}
256			if !ar.Destroyed {
257				if ar.ManifestID != "" {
258					return fmt.Errorf(
259						"retention: 档案 %s 未销毁却挂有清册申请编号 %s，记录已损坏: %w",
260						id, ar.ManifestID, ErrCorruptState)
261				}
262				continue
263			}
264			if ar.ManifestID == "" {
265				return fmt.Errorf(
266					"retention: 档案 %s 已销毁但没有记录所属清册的申请编号，记录已损坏: %w",
267					id, ErrCorruptState)
268			}
269			rec, ok := data.Manifests[ar.ManifestID]
270			if !ok || rec == nil {
271				return fmt.Errorf(
272					"retention: 档案 %s 已销毁，但其所属清册 %s 不存在，记录已损坏: %w",
273					id, ar.ManifestID, ErrCorruptState)
274			}
275			count := 0
276			for _, e := range rec.Entries {
277				if e.ID == id {
278					count++
279				}
280			}
281			if count != 1 {
282				return fmt.Errorf(
283					"retention: 档案 %s 在其所属清册 %s 中收录 %d 次（应恰好一次），记录已损坏: %w",
284					id, ar.ManifestID, count, ErrCorruptState)
285			}
286		}
287	
288		applicationIDs := make([]string, 0, len(data.Manifests))
289		for id := range data.Manifests {
290			applicationIDs = append(applicationIDs, id)
291		}
292		sort.Strings(applicationIDs)
293		for _, appID := range applicationIDs {
294			rec := data.Manifests[appID]
295			if rec == nil {
296				return fmt.Errorf(
297					"retention: 清册 %s 的内容缺失，记录已损坏: %w",
298					appID, ErrCorruptState)
299			}
300			seen := make(map[string]int, len(rec.Entries))
301			for _, e := range rec.Entries {
302				seen[e.ID]++
303				ar, ok := data.Archives[e.ID]
304				if !ok || ar == nil {
305					return fmt.Errorf(
306						"retention: 清册 %s 收录的档案 %s 不存在，记录已损坏: %w",
307						appID, e.ID, ErrCorruptState)
308				}
309				if !ar.Destroyed {
310					return fmt.Errorf(
311						"retention: 清册 %s 收录的档案 %s 未标记为已销毁，记录已损坏: %w",
312						appID, e.ID, ErrCorruptState)
313				}
314				if ar.ManifestID != appID {
315					return fmt.Errorf(
316						"retention: 清册 %s 收录的档案 %s 归属另一申请 %s，记录已损坏: %w",
317						appID, e.ID, ar.ManifestID, ErrCorruptState)
318				}
319			}
320			// 同一档案被同一份清册重复收录（档案侧的恰好一次检查只覆盖
321			// 归属指向该清册的情况，这里对全部收录记录再核对一遍）。
322			entryIDs := make([]string, 0, len(seen))
323			for id := range seen {
324				entryIDs = append(entryIDs, id)
325			}
326			sort.Strings(entryIDs)
327			for _, id := range entryIDs {
328				if seen[id] > 1 {
329					return fmt.Errorf(
330						"retention: 清册 %s 重复收录档案 %s（共 %d 次），记录已损坏: %w",
331						appID, id, seen[id], ErrCorruptState)
332				}
333			}
334		}
335		return nil
336	}
337	
338	// validateRevisionContinuity 检查每份档案的最初截止日、修订记录与当前截止日
339	// 是否连续对应。
340	//
341	// 正常办理保存的记录必然满足：第一条修订的原截止日等于最初截止日，后续每条
342	// 的原截止日等于上一条的新截止日，最后一条的新截止日等于当前截止日；没有
343	// 修订时最初截止日与当前截止日相同。修订日期仅用于记录办理时间，不决定生效
344	// 先后，因此历史不按修订日期重新排列，只按保存顺序核对衔接；期限被延长、
345	// 缩短或改回早先用过的日期，只要衔接完整都是合法记录。
346	//
347	// 出现断开的修订关系、当前截止日与末次修订的新截止日不符、修订列表中存在
348	// 空记录，或已有修订却缺少最初截止日（不能把当前期限冒充最初期限）时，
349	// 保存内容已无法说明期限如何演变，返回可由 ErrCorruptState 识别的错误，
350	// 并在信息中给出涉及的档案编号；能对应到具体修订时同时给出修订编号。
351	// 校验覆盖整个保管库的全部档案（含已销毁的），与本次办理名单无关。
352	func validateRevisionContinuity(data *storeData) error {
353		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
354		archiveIDs := make([]string, 0, len(data.Archives))
355		for id := range data.Archives {
356			archiveIDs = append(archiveIDs, id)
357		}
358		sort.Strings(archiveIDs)
359		for _, id := range archiveIDs {
360			ar := data.Archives[id]
361			if ar == nil {
362				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
363				continue
364			}
365			if len(ar.Revisions) == 0 {
366				// 没有修订时最初截止日与当前截止日必须相同
367				// （旧记录缺少最初截止日的情形已在 load 中按登记截止日补齐）。
368				if !ar.InitialEnd.Equal(ar.End) {
369					return fmt.Errorf(
370						"retention: 档案 %s 没有修订记录，但最初截止日 %s 与当前截止日 %s 不一致，记录已损坏: %w",
371						id, ar.InitialEnd, ar.End, ErrCorruptState)
372				}
373				continue
374			}
375			for i, rec := range ar.Revisions {
376				if rec == nil {
377					return fmt.Errorf(
378						"retention: 档案 %s 的修订列表第 %d 条为空记录，记录已损坏: %w",
379						id, i+1, ErrCorruptState)
380				}
381			}
382			if ar.InitialEnd.IsZero() {
383				return fmt.Errorf(
384					"retention: 档案 %s 已有修订记录（首条为 %s）却缺少最初截止日，记录已损坏: %w",
385					id, ar.Revisions[0].ID, ErrCorruptState)
386			}
387			// 按保存顺序逐条核对衔接：每条的原截止日必须等于此前生效的截止日。
388			expected := ar.InitialEnd
389			for _, rec := range ar.Revisions {
390				if !rec.OldEnd.Equal(expected) {
391					return fmt.Errorf(
392						"retention: 档案 %s 的修订 %s 的原截止日 %s 与此前生效的截止日 %s 不衔接，记录已损坏: %w",
393						id, rec.ID, rec.OldEnd, expected, ErrCorruptState)
394				}
395				expected = rec.NewEnd
396			}
397			if !ar.End.Equal(expected) {
398				return fmt.Errorf(
399					"retention: 档案 %s 的当前截止日 %s 与末次修订 %s 的新截止日 %s 不符，记录已损坏: %w",
400					id, ar.End, ar.Revisions[len(ar.Revisions)-1].ID, expected, ErrCorruptState)
401			}
402		}
403		return nil
404	}
405	
406	// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
407	// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
408	func (s *Store) save(data *storeData) error {
409		buf, err := json.MarshalIndent(data, "", "  ")
410		if err != nil {
411			return fmt.Errorf("retention: 状态编码失败: %w", err)
412		}
413		tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
414		if err != nil {
415			return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
416		}
417		tmpName := tmp.Name()
418		cleanup := func() { _ = os.Remove(tmpName) }
419		if _, err := tmp.Write(buf); err != nil {
420			tmp.Close()
421			cleanup()
422			return fmt.Errorf("retention: 写入状态失败: %w", err)
423		}
424		if err := tmp.Sync(); err != nil {
425			tmp.Close()
426			cleanup()
427			return fmt.Errorf("retention: 刷盘状态失败: %w", err)
428		}
429		if err := tmp.Close(); err != nil {
430			cleanup()
431			return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
432		}
433		if err := os.Rename(tmpName, s.statePath()); err != nil {
434			cleanup()
435			return fmt.Errorf("retention: 替换状态文件失败: %w", err)
436		}
437		// 刷目录，确保 rename 在崩溃后仍然落盘。
438		if dir, err := os.Open(s.dir); err == nil {
439			_ = dir.Sync()
440			_ = dir.Close()
441		}
442		return nil
443	}
444	
445	// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
446	// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
447	func (s *Store) mutate(fn func(*storeData) error) error {
448		s.opMu.Lock()
449		defer s.opMu.Unlock()
450		unlock, err := s.lock()
451		if err != nil {
452			return err
453		}
454		defer unlock()
455		data, err := s.load()
456		if err != nil {
457			return err
458		}
459		if err := fn(data); err != nil {
460			return err
461		}
462		return s.save(data)
463	}
464	
465	// view 在共享锁内重读状态并执行只读查询。
466	func (s *Store) view(fn func(*storeData) error) error {
467		s.opMu.RLock()
468		defer s.opMu.RUnlock()
469		unlock, err := s.rlock()
470		if err != nil {
471			return err
472		}
473		defer unlock()
474		data, err := s.load()
475		if err != nil {
476			return err
477		}
478		return fn(data)
479	}
480

