1	package retention
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 已保存的最初截止日、修订记录与当前截止日必须连续对应：
10	// 第一条修订的原截止日等于最初截止日，后续每条的原截止日等于上一条的
11	// 新截止日，最后一条的新截止日等于当前截止日；没有修订时最初截止日与
12	// 当前截止日相同。出现断开的修订关系、当前截止日与末次修订不符、
13	// 修订列表中存在空记录，或已有修订却缺少最初截止日时，Open 必须按
14	// 记录损坏失败（ErrCorruptState），错误信息指出档案编号，能对应到
15	// 具体修订时同时指出修订编号，原文件保持原样。
16	func TestOpenRejectsBrokenRevisionChain(t *testing.T) {
17		archive := func(initial, end, revisions string) string {
18			head := `{"id":"A-1","category":"合同","start":"2020-01-01","end":"` + end + `",`
