48					`,"revisions":[`+rev("R-1", "2025-01-10", "2026-01-10")+`,`+rev("R-2", "2026-02-01", "2027-01-10")+`]`)),
49				[]string{"A-1", "R-2"},
50			},
51			"修订列表中存在空记录": {
52				state(archive("2025-01-10", "2025-01-10", `,"revisions":[null]`)),
53				[]string{"A-1"},
54			},
55			"已有修订却缺少最初截止日": {
56				state(archive("", "2026-01-10",
57					`,"revisions":[`+rev("R-1", "2025-01-10", "2026-01-10")+`]`)),
58				[]string{"A-1", "R-1"},
