73					t.Fatal("修订关系不衔接时不应打开成功")
74				}
75				if !errors.Is(err, ErrCorruptState) {
76					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
77				}
78				for _, id := range tc.wantIDs {
