90	// 期限被延长、缩短或改回早先用过的日期，只要修订衔接完整就应正常读取；
91	// 修订日期仅用于记录，历史不按该日期重新排列。核对与销毁按当前生效的
92	// 截止日判断，截止日当天即到期。
93	func TestValidRevisionChainsKeepWorking(t *testing.T) {
94		archive := func(end string, revisions string) string {
95			return `{"id":"A-1","category":"合同","start":"2020-01-01","end":"` + end +
96				`","initial_end":"2025-01-10","destroyed":false,"freezes":[]` + revisions + `}`
97		}
98		rev := func(id, oldEnd, newEnd, on string) string {
99			return `{"id":"` + id + `","old_end":"` + oldEnd + `","new_end":"` + newEnd +
100				`","revised_on":"` + on + `","reason":"调整"}`
101		}
102		state := func(archiveJSON string) string {
103			return `{"version":1,"archives":{"A-1":` + archiveJSON + `},"manifests":{}}`
104		}
105	
106		chains := map[string]struct {
107			state      string
108			currentEnd string
109			revisions  int
110		}{
111			"延长": {
112				state(archive("2026-01-10", `,"revisions":[`+rev("R-1", "2025-01-10", "2026-01-10", "2024-12-01")+`]`)),
113				"2026-01-10", 1,
