121					rev("R-1", "2025-01-10", "2026-01-10", "2024-12-01")+`,`+
122					rev("R-2", "2026-01-10", "2025-01-10", "2025-01-05")+`]`)),
123				"2025-01-10", 2,
124			},
125			"修订日期乱序仍按保存顺序衔接": {
