263			func() ReviseInput { in := base; in.Reason = "其他原因"; return in }(),
264		}
265		for i, in := range variants {
266			if _, err := s.Revise(in); !errors.Is(err, ErrRevisionConflict) {
267				t.Fatalf("变体 %d 应返回编号冲突，得到 %v", i, err)
268			}
269		}
270	
271		// 修订编号全库唯一：另一档案也不能复用同一编号办理不同内容。
272		in := base
273		in.ArchiveID = "A-002"
274		if _, err := s.Revise(in); !errors.Is(err, ErrRevisionConflict) {
275			t.Fatalf("跨档案复用编号应冲突，得到 %v", err)
276		}
